from io import BytesIO

def extract_sequence_files(zip_file_path):
    sequences = {}
    with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
        for file_name in zip_ref.namelist():
            if file_name.endswith('.fasta'):
                with zip_ref.open(file_name) as file:
                    content = file.read().decode('utf-8')
                    sequences[file_name] = content.split('>')[1:]
    return sequences

def process_sequences(sequences):
    processed_data = {}
    for file_name, contents in sequences.items():
        processed_content = []
        for content in contents:
            parts = content.strip().split('\n')
            header = parts[0]
            sequence = ''.join(parts[1:])
            # Example processing: count the number of 'A' bases
            a_count = sequence.count('A')
            processed_content.append((header, a_count))
        processed_data[file_name] = processed_content
    return processed_data

def save_results(results, output_dir):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)
    for file_name, data in results.items():
        output_path = os.path.join(output_dir, f"{file_name.replace('.fasta', '_output.txt')}")
        with open(output_path, 'w') as file:
            for header, count in data:
                file.write(f">{header}\tCount of A: {count}\n")

