import requests
from gzip import decompress
from io import BytesIO

def analyze_gzip_compression_ratio(urls):
    results = {}
    for url in urls:
        try:
            response = requests.get(url)
            if response.status_code == 200:
                original_size = len(response.content)
                try:
                    # Attempt to decode gzip compressed content
                    decompressed_content = decompress(response.content)
                    compressed_size = len(decompressed_content) // 1024  # Convert bytes to KB
                    results[url] = (original_size, compressed_size)
                except OSError:
                    # Content is not compressed
                    results[url] = (original_size, 0)
        except requests.RequestException as e:
            print(f"Error fetching {url}: {e}")
    return results

# Example usage
urls = [
    'https://example.com/file1.html',
    'https://example.com/file2.pdf',
    'https://example.com/file3.txt'
]
compression_results = analyze_gzip_compression_ratio(urls)

for url, (original, compressed) in compression_results.items():
    if compressed > 0:
        ratio = (compressed / original) * 100
        print(f"{url}: Original size {original}KB, Compressed size {compressed}KB, Compression ratio {ratio:.2f}%")
    else:
        print(f"{url}: Not compressed")
```
