            source_file_path = os.path.join(root, file)
            dest_file_hashes = {dest: None for dest in destination_dirs}

            for dest in destination_dirs:
                dest_file_path = os.path.join(dest, file[2:])
                if os.path.exists(dest_file_path):
                    dest_file_hashes[dest] = compute_hash(dest_file_path)

            if any(hash_val != dest_file_hashes[dest] for dest, hash_val in dest_file_hashes.items()):
                rsync = Rsync()
