def get_all_urls(base_url):
    urls = set()
    visited = set()

    def scrape(url):
        if url not in visited:
            visited.add(url)
            try:
                response = requests.get(url)
                soup = BeautifulSoup(response.text, 'html.parser')
                base_domain = "{uri.scheme}://{uri.netloc}".format(uri=urlparse(base_url))
                for link in soup.find_all('a'):
                    href = link.get('href')
                    if href:
                        full_url = urljoin(base_domain, href)
                        if is_valid_url(full_url) and is_same_domain(full_url, base_domain):
                            urls.add(full_url)
                            scrape(full_url)
            except Exception as e:
                print(f"Error scraping {url}: {e}")

    scrape(base_url)
    return urls

def is_valid_url(url):
    parsed = urlparse(url)
    return bool(parsed.netloc) and bool(parsed.scheme)

def is_same_domain(url, domain):
    parsed_url = urlparse(url)
    parsed_domain = urlparse(domain)
    return parsed_url.netloc == parsed_domain.netloc

def generate_html_sitemap(urls, output_file='sitemap.html'):
    with open(output_file, 'w') as f:
        f.write("<ul>\n")
        for url in sorted(urls):
            f.write(f"<li><a href='{url}'>{url}</a></li>\n")
        f.write("</ul>")

